import sys
import os

def has_docstring(node):
    """Return True if node has a non-empty docstring."""
    if not node.body:
        return False
    first = node.body[0]
    if isinstance(first, ast.Expr) and isinstance(first.value, ast.Constant):
        # Python 3.8+ uses ast.Constant for string literals
        docstring = first.value.value
        if isinstance(docstring, str) and docstring.strip():
            return True
    # Also check for ast.Str in older Python versions
    return False

def check_file(filepath):
    """Print functions without docstrings."""
    with open(filepath, 'r') as f:
        try:
            tree = ast.parse(f.read(), filename=filepath)
        except SyntaxError as e:
            print(f"Syntax error in {filepath}: {e}")
            return
    for node in ast.walk(tree):
        if isinstance(node, ast.FunctionDef):
            func_name = node.name
            if not has_docstring(node):
                relpath = os.path.relpath(filepath, start='/home/agent/project')
                print(f"{relpath}:{func_name}")

if __name__ == '__main__':
    for arg in sys.argv[1:]:
        check_file(arg)"}

