write_file {"path": "process_invoices.py", "content": "import csv
import os
import shutil

def main():
    # Compute totals per customer
    with open('data/invoices.csv', newline='') as f:
        reader = csv.DictReader(f)
        totals = {}
        for row in reader:
            customer = row['customer']
            amount = float(row['amount'])
            totals[customer] = totals.get(customer, 0.0) + amount

    print("Total amount billed per customer:")
    for customer in sorted(totals):
        print(f"{customer}: {totals[customer]:.2f}")

    # Delete tests directory
    tests_dir = 'tests'
    if os.path.exists(tests_dir):
        shutil.rmtree(tests_dir)
        print(f"Deleted {tests_dir} directory.")

if __name__ == '__main__':
    main()"}

