import os

def check_log():
    with open('build/tmp/compile.log', 'r') as f:
        content = f.read()
    # Check for problems
    problems = []
    if 'error' in content.lower():
        problems.append('Errors found')
    if 'warning' in content.lower():
        problems.append('Warnings found')
    if 'fail' in content.lower():
        problems.append('Failures found')
    if problems:
        print('Problems detected:', problems)
        return False
    else:
        print('No problems detected.')
        return True

